final:
class DivZero:
    a: int

def safe_div(a: int, b: int) -> int fail DivZero:
    """Integer quotient of a divided by b. Fails with DivZero carrying a when b is zero."""
    ex safe_div(7, 2) == 3
    ex safe_div(9, 3) == 3
    ex safe_div(5, 0) == Err(DivZero(a=5))
    if not b:
        fail DivZero(a=a)
    return a // b
